-- 181: Original BrillaPrep WASSCE BrillaPrep transitional Woodwork beta content blueprint questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_181_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_181_guard;
INSERT INTO _migration_181_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_006' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_2' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is seasoning of timber?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Permanent soaking to increase green weight","B. Controlled reduction of moisture to a level suitable for use","C. Coating end grain before conversion only","D. Removing all natural grain from the wood"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Seasoning improves dimensional stability, strength-to-weight performance and resistance to some forms of decay when properly controlled. Therefore the correct answer is B: Controlled reduction of moisture to a level suitable for use.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_006' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_181_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_007' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_2' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are board ends sometimes sealed during seasoning?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Force all moisture to leave through the ends faster","B. Prevent any moisture movement from the board","C. Slow rapid end-grain moisture loss and reduce checking","D. Make the end grain softer than the centre"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Moisture escapes quickly through end grain, so sealing helps equalise drying rates and limits tensile stresses that open end checks. Therefore the correct answer is C: Slow rapid end-grain moisture loss and reduce checking.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_007' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_181_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_008' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_2' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which conversion method tends to produce boards with more stable width and straighter grain?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Through-and-through sawing only","B. Random cross-cutting across the log","C. Peeling the log into end-grain discs","D. Quarter sawing"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Quarter-sawn growth rings are oriented more nearly perpendicular to the face, reducing tangential width movement and often producing straighter grain. Therefore the correct answer is D: Quarter sawing.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_008' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_181_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_009' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_2' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What commonly causes cupping in a wide timber board?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Unequal shrinkage and growth-ring orientation across its section","B. Perfectly uniform moisture on every face","C. Correct support and balanced grain","D. The absence of any moisture movement"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Tangential and radial shrinkage differ, so boards can curve across their width as moisture content changes unevenly. Therefore the correct answer is A: Unequal shrinkage and growth-ring orientation across its section.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_009' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_181_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_010' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_2' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which condition most strongly encourages fungal decay in timber?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Dry timber kept below decay-supporting moisture","B. Sustained moisture with suitable temperature and oxygen","C. A clean finished surface in a ventilated room","D. Low moisture with no fungal access"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Decay fungi require available moisture as well as oxygen and favourable temperature, so keeping timber dry is a primary protection strategy. Therefore the correct answer is B: Sustained moisture with suitable temperature and oxygen.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_010' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
